// Concatenates engine/*.js (shared-scope sources) into one ES module: src/engine.generated.js
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const ORDER = ['core.js','rig_cat.js','rig_quad.js','rig_bird.js','rig_rept.js','rig_croc.js','rig_horse.js','rig_water.js','rig_bugs.js','catalog.js'];
const body = ORDER.map(f => `// ---- engine/${f} ----\n` + readFileSync(join(root,'engine',f),'utf8')).join('\n');
const out = `/* AUTO-GENERATED by scripts/build.mjs — edit files in engine/ and run \`npm run build\`. */\n` + body +
  `\nexport { PAL, SL, N, PATTERNS, PATTERN_LABELS, RIGS, RIG_POSES, DEFAULT_POSES, posesOf, buildSprite, colorize, CATALOG, TYPES, byId, nearestPal, shadeOf, lightOf, hexRgb, lum, KINDS, kindOf, matchPreset, presetZones };\n`;
writeFileSync(join(root,'src','engine.generated.js'), out);
console.log('built src/engine.generated.js', out.length, 'bytes');
